const { Worker } = require('worker_threads');
const worker = new Worker('./worker.js');
worker.on('message', () => {
  console.log('Result')
});
worker.on('error', (error) => {
  console.error(error)
});
worker.on('exit', (code)=> {
  console.log('Worker stopped', code)
})
